mapper.select:
SELECT a.id, a.exam_id AS examId, a.user_id AS userId, a.subject_type AS subjectType, a.subject_name AS subjectName, a.candidate_no AS candidateNo, a.mobile, a.email, a.depart_id AS departId, d.dept_name AS departName, a.position_id AS positionId, p.name AS positionName, a.target_grade_id AS targetGradeId, g.name AS targetGradeName, a.batch_no AS batchNo, a.valid_from AS validFrom, a.expire_at AS expireAt, CASE WHEN a.status IN ('ASSIGNED', 'STARTED') AND a.expire_at < NOW() THEN 'EXPIRED' ELSE a.status END AS status, a.paper_id AS paperId, paper.passed, e.title AS examTitle, a.activated_at AS activatedAt, a.submitted_at AS submittedAt, a.completed_at AS completedAt, a.disabled_reason AS disabledReason, a.create_time AS createTime FROM el_exam_assignment a JOIN el_position p ON p.id = a.position_id LEFT JOIN el_sys_depart d ON d.id = a.depart_id LEFT JOIN el_position_grade g ON g.id = a.target_grade_id JOIN el_exam e ON e.id = a.exam_id LEFT JOIN el_paper paper ON paper.id = a.paper_id
a.subject_type = 'CANDIDATE'
AND a.subject_name LIKE CONCAT('%', #{query.subjectName}, '%')
AND a.position_id = #{query.positionId}
AND a.depart_id = #{query.departId}
AND a.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND (CASE WHEN a.status IN ('ASSIGNED', 'STARTED') AND a.expire_at < NOW() THEN 'EXPIRED' ELSE a.status END) = #{query.status}
AND paper.passed = #{query.passed}
AND a.valid_from >= #{query.validFrom}
AND a.expire_at <= #{query.expireTo}
ORDER BY a.create_time DESC
